CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS agents(name TEXT PRIMARY KEY,last_seen INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS groups(chat INTEGER PRIMARY KEY,name TEXT NOT NULL,connected INTEGER NOT NULL,available INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS topics(id TEXT PRIMARY KEY,chat INTEGER NOT NULL REFERENCES groups(chat),thread INTEGER NOT NULL,name TEXT NOT NULL,owner TEXT REFERENCES agents(name),closed INTEGER NOT NULL DEFAULT 0,UNIQUE(chat,thread));
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY AUTOINCREMENT,topic TEXT NOT NULL REFERENCES topics(id),agent TEXT REFERENCES agents(name),user INTEGER,content TEXT NOT NULL,sent_at INTEGER NOT NULL,quote INTEGER REFERENCES messages(id));
CREATE INDEX IF NOT EXISTS messages_topic_order ON messages(topic,id);
CREATE TABLE IF NOT EXISTS subscriptions(agent TEXT NOT NULL REFERENCES agents(name),topic TEXT NOT NULL REFERENCES topics(id),active INTEGER NOT NULL,muted INTEGER NOT NULL,acked INTEGER REFERENCES messages(id),PRIMARY KEY(agent,topic));
CREATE TABLE IF NOT EXISTS telegram_messages(chat INTEGER NOT NULL,telegram_id INTEGER NOT NULL,message INTEGER NOT NULL REFERENCES messages(id),PRIMARY KEY(chat,telegram_id));
CREATE TABLE IF NOT EXISTS updates(id INTEGER PRIMARY KEY,raw TEXT);
CREATE TABLE IF NOT EXISTS outbox(id INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT NOT NULL,message INTEGER REFERENCES messages(id),chat INTEGER NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_attempt INTEGER NOT NULL DEFAULT 0,error TEXT,UNIQUE(kind,message));
CREATE INDEX IF NOT EXISTS outbox_due ON outbox(status,next_attempt,id);
CREATE TABLE IF NOT EXISTS management(id INTEGER PRIMARY KEY AUTOINCREMENT,time INTEGER NOT NULL,kind TEXT NOT NULL,detail TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,trusted INTEGER NOT NULL DEFAULT 0,language TEXT);
PRAGMA user_version=1;
